def power(base, exp, mod):
    res = 1
    base %= mod
    while exp > 0:
        if exp % 2 == 1:
            res = (res * base) % mod
        base = (base * base) % mod
        exp //= 2
    return res

MOD = 10000
base = 3
# phi(10000) = 4000
PHI = 4000 

print("Searching for the order of 3 modulo 10000...")

for k in range(1, PHI + 1):
    if power(base, k, MOD) == 1:
        print(f"Order k found: {k}")
        break
else:
    print("Order not found within PHI.")
